const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,math,collections,statistics,os
for step in [0,30,60]:
 p=f'/workspace/outputs/val_generations/{step}.jsonl'
 rows=[json.loads(x) for x in open(p)]
 def num(s):
  ms=re.findall(r'####\s*(-?[0-9][0-9,]*(?:\.[0-9]+)?)',s)
  return ms[-1].replace(',','') if ms else None
 def eq(a,b):
  try:return math.isclose(float(a),float(b),rel_tol=0,abs_tol=1e-9)
  except:return False
 corr=[eq(num(r['output']),str(r['gts'])) for r in rows]
 # compare stored score/acc
 print(step,'n',len(rows),'grader acc',sum(corr)/len(corr),'stored score',sum(float(r.get('score',0)) for r in rows)/len(rows),'stored acc',sum(float(r.get('acc',0)) for r in rows)/len(rows),'missing',sum(num(r['output']) is None for r in rows))
 print('step counts',collections.Counter(r.get('step') for r in rows).most_common(5),'output lens',statistics.mean(len(r['output']) for r in rows),max(len(r['output']) for r in rows))
 # mismatch examples
 for r,c in zip(rows,corr):
  if c != bool(r.get('score',0)):
   print('mismatch',r['gts'],repr(num(r['output'])),r.get('score'),repr(r['output'][-450:])); break
# inspect validation differences by idx/input
rows0=[json.loads(x) for x in open('/workspace/outputs/val_generations/0.jsonl')]
rows60=[json.loads(x) for x in open('/workspace/outputs/val_generations/60.jsonl')]
print('same ordering input',all(a['input']==b['input'] for a,b in zip(rows0,rows60)))
# score distributions
for step in [0,30,60]:
 rows=[json.loads(x) for x in open(f'/workspace/outputs/val_generations/{step}.jsonl')]
 print(step,'stored',collections.Counter((r.get('score'),r.get('acc')) for r in rows).most_common(10))
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":30000});
text(r.output);

